  "analysis/inference/interaction.py|def interaction(|10": {
   "file": "analysis/inference/interaction.py",
   "line": 22,
   "text": "def interaction(groups: Sequence[Sequence[float]], center: LogCenter) -> float:\n    if len(groups) == len(Pair._fields):\n        pair = Pair(*groups)\n        return difference(pair.numerator, pair.denominator, center)\n    quad = Quad(*groups)\n    # On logs a difference is a ratio, log(a) - log(b) = log(a / b), so each inner difference is\n    # \"how many times slower is a than b\", e.g. atomic over local for RQ2. Their difference, Δr, asks\n    # whether that slowdown is bigger in the browser than natively; exp(Δr) is the ratio of ratios\n    # (bA / bL) / (nA / nL) of the centres, 1 meaning the same gap.\n    browser = difference(quad.browser_numerator, quad.browser_denominator, center)"
  },
  "analysis/runs.py|# One value per run, never per iteration|5": {
   "file": "analysis/runs.py",
   "line": 28,
   "text": "# One value per run, never per iteration: the run is the unit of analysis (Georges et al. 2007,\n# https://doi.org/10.1145/1297027.1297033).\ndef run_summaries(rows: Iterable[Row], summary: Summary) -> list[RunSummary]:\n    times, configurations = measured_times(rows)\n    return [RunSummary(run, configurations[run], summary.of(values)) for run, values in times.items()]"
  },
  "analysis/scaling/karp_flatt.py|def serial_fraction(speedup|4": {
   "file": "analysis/scaling/karp_flatt.py",
   "line": 16,
   "text": "def serial_fraction(speedup: float, threads: int) -> float:\n    if threads < 2:\n        raise ValueError(\"the serial fraction needs N > 1\")\n    return (1 / speedup - 1 / threads) / (1 - 1 / threads)"
  },
  "analysis/scaling/table.py|def speedup_of(|5": {
   "file": "analysis/scaling/table.py",
   "line": 33,
   "text": "def speedup_of(baseline: Sequence[float], values: Sequence[float], center: Summary) -> Speedup:\n    def ratio(groups: list[list[float]]) -> float:\n        return center.of(groups[0]) / center.of(groups[1])\n\n    return Speedup(center.of(baseline) / center.of(values), bootstrap_interval([baseline, values], ratio))"
  },
  "analysis/stats/bootstrap.py|# Each group is resampled on its own|9": {
   "file": "analysis/stats/bootstrap.py",
   "line": 32,
   "text": "# Each group is resampled on its own: the groups are runs of different configurations, which are\n# independent processes, so there is no pairing to keep.\n# A seeded Monte Carlo: recompute the statistic on 10 000 resamples and sort the results; their\n# spread stands in for the sampling error, and the fixed seed makes every rerun give the same\n# interval.\ndef bootstrap_distribution(groups: Groups, statistic: Statistic, resamples: int, seed: int) -> list[float]:\n    generator = random.Random(seed)\n    return sorted(statistic(resample(generator, groups)) for _ in range(resamples))\n"
  },
  "analysis/stats/bootstrap.py|def percentile_interval(|4": {
   "file": "analysis/stats/bootstrap.py",
   "line": 44,
   "text": "def percentile_interval(distribution: Sequence[float], confidence: float) -> Interval:\n    tail = (1 - confidence) / 2\n    last = len(distribution) - 1\n    return Interval(distribution[round(tail * last)], distribution[round((1 - tail) * last)])"
  },
  "analysis/stats/bootstrap.py|def resample(|2": {
   "file": "analysis/stats/bootstrap.py",
   "line": 28,
   "text": "def resample(generator: random.Random, groups: Groups) -> list[list[float]]:\n    return [generator.choices(group, k=len(group)) for group in groups]"
  },
  "analysis/stats/cliff.py|def cliffs_delta(|8": {
   "file": "analysis/stats/cliff.py",
   "line": 5,
   "text": "def cliffs_delta(baseline: Sequence[float], treatment: Sequence[float]) -> float:\n    above = sum(t > b for t in treatment for b in baseline)\n    below = sum(t < b for t in treatment for b in baseline)\n    return (above - below) / (len(baseline) * len(treatment))"
  },
  "analysis/stats/holm.py|def holm_adjusted(|11": {
   "file": "analysis/stats/holm.py",
   "line": 6,
   "text": "def holm_adjusted(p_values: Sequence[float]) -> list[float]:\n    # Indices sorted by p, like `[...p.keys()].sort((a, b) => p[a] - p[b])`. The smallest p pays\n    # the full m-fold penalty and each later one less, since one fewer hypothesis is left to test;\n    # it controls the family error like Bonferroni but is never less powerful.\n    order = sorted(range(len(p_values)), key=lambda index: p_values[index])\n    adjusted = [0.0] * len(p_values)\n    running = 0.0\n    for rank, index in enumerate(order):\n        running = max(running, min(1.0, (len(p_values) - rank) * p_values[index]))\n        adjusted[index] = running\n    return adjusted"
  },
